import{_ as e,o as s,c as l,a2 as t}from"./chunks/framework.DQbZ8cc1.js";const b=JSON.parse('{"title":"发布包安装","description":"","frontmatter":{},"headers":[],"relativePath":"zh/docs/installation/release.md","filePath":"zh/docs/installation/release.md"}'),i={name:"zh/docs/installation/release.md"};function n(o,a,d,r,h,c){return s(),l("div",null,[...a[0]||(a[0]=[t(`<h1 id="发布包安装" tabindex="-1">发布包安装 <a class="header-anchor" href="#发布包安装" aria-label="Permalink to “发布包安装”">​</a></h1><p>如果你不使用 Docker，发布包是推荐的安装方式。</p><h2 id="环境要求" tabindex="-1">环境要求 <a class="header-anchor" href="#环境要求" aria-label="Permalink to “环境要求”">​</a></h2><ul><li>操作系统：Windows / macOS / Linux</li><li>内存：建议 2GB+</li><li>数据库： <ul><li>本地体验和小型站点可使用 SQLite</li><li>生产环境建议 MySQL 8+</li></ul></li></ul><h2 id="下载发布包" tabindex="-1">下载发布包 <a class="header-anchor" href="#下载发布包" aria-label="Permalink to “下载发布包”">​</a></h2><p>发布地址：<a href="https://github.com/mlogclub/bbs-go/releases/latest" target="_blank" rel="noreferrer">https://github.com/mlogclub/bbs-go/releases/latest</a></p><table tabindex="0"><thead><tr><th>平台</th><th>文件名</th></tr></thead><tbody><tr><td>Windows</td><td><code>bbs-go-windows-x86_64.zip</code></td></tr><tr><td>macOS Intel</td><td><code>bbs-go-macos-amd64.zip</code></td></tr><tr><td>macOS Apple 芯片</td><td><code>bbs-go-macos-arm64.zip</code></td></tr><tr><td>Linux 64 位</td><td><code>bbs-go-linux-amd64.zip</code></td></tr><tr><td>Linux 32 位</td><td><code>bbs-go-linux-386.zip</code></td></tr></tbody></table><h2 id="发布包目录结构" tabindex="-1">发布包目录结构 <a class="header-anchor" href="#发布包目录结构" aria-label="Permalink to “发布包目录结构”">​</a></h2><p>解压后目录中包含可执行程序和内置资源：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;release-root&gt;/</span></span>
<span class="line"><span>├── bbs-go</span></span>
<span class="line"><span>├── res/</span></span>
<span class="line"><span>├── locales/</span></span>
<span class="line"><span>└── site/</span></span></code></pre></div><h2 id="启动-bbs-go" tabindex="-1">启动 BBS-GO <a class="header-anchor" href="#启动-bbs-go" aria-label="Permalink to “启动 BBS-GO”">​</a></h2><p>在解压目录中运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux/macOS</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bbs-go</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bbs-go.exe</span></span></code></pre></div><p>默认端口：<code>8082</code>。</p><h2 id="首次安装" tabindex="-1">首次安装 <a class="header-anchor" href="#首次安装" aria-label="Permalink to “首次安装”">​</a></h2><p>打开：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://localhost:8082/install</span></span></code></pre></div><p>安装向导步骤：</p><ol><li>选择语言（<code>en-US</code> / <code>zh-CN</code>）。</li><li>选择数据库。</li><li>填写站点信息。</li><li>创建管理员账号。</li><li>完成安装。</li></ol><p>本地体验可选择 SQLite。生产环境建议使用 MySQL 8+。</p><h2 id="访问地址" tabindex="-1">访问地址 <a class="header-anchor" href="#访问地址" aria-label="Permalink to “访问地址”">​</a></h2><ul><li>前台：<code>http://localhost:8082/</code></li><li>管理后台：<code>http://localhost:8082/dashboard</code></li><li>API：<code>http://localhost:8082/api/*</code></li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to “常见问题”">​</a></h2><h3 id="端口被占用" tabindex="-1">端口被占用 <a class="header-anchor" href="#端口被占用" aria-label="Permalink to “端口被占用”">​</a></h3><p>修改 <code>bbs-go.yaml</code> 中的 <code>Port</code>，或停止占用端口的进程。</p><h3 id="数据库连接失败" tabindex="-1">数据库连接失败 <a class="header-anchor" href="#数据库连接失败" aria-label="Permalink to “数据库连接失败”">​</a></h3><ul><li>MySQL：检查地址、端口、用户名、密码、数据库名。</li><li>SQLite：直接在安装向导中选择 SQLite，无需手工准备数据库。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./production.html">生产环境部署</a></li><li><a href="./docker.html">Docker 部署</a></li><li><a href="./server/google-login.html">Google 登录配置</a></li></ul>`,29)])])}const g=e(i,[["render",n]]);export{b as __pageData,g as default};
